# ! [doc = " A lot of UNIX platforms don't have a specialized way to register TLS"] # ! [doc = " destructors for native TLS. Instead, we use one TLS key with a destructor"] # ! [doc = " that will run all native TLS destructors in the destructor list."] use split_decls_genesis :: ourprelude :: * ; use crate :: ptr ; use crate :: sys :: thread_local :: key :: { LazyKey , set } ; #[cfg (target_thread_local)] pub fn enable () { use crate :: sys :: thread_local :: destructors ; static DTORS : LazyKey = LazyKey :: new (Some (run)) ; unsafe { set (DTORS . force () , ptr :: without_provenance_mut (1)) ; } unsafe extern "C" fn run (_ : * mut u8) { unsafe { destructors :: run () ; crate :: rt :: thread_cleanup () ; } } } #[doc = " On platforms with key-based TLS, the system runs the destructors for us."] #[doc = " We still have to make sure that [`crate::rt::thread_cleanup`] is called,"] #[doc = " however. This is done by deferring the execution of a TLS destructor to"] #[doc = " the next round of destruction inside the TLS destructors."] #[cfg (not (target_thread_local))] pub fn enable () { const DEFER : * mut u8 = ptr :: without_provenance_mut (1) ; const RUN : * mut u8 = ptr :: without_provenance_mut (2) ; static CLEANUP : LazyKey = LazyKey :: new (Some (run)) ; unsafe { set (CLEANUP . force () , DEFER) } unsafe extern "C" fn run (state : * mut u8) { if state == DEFER { unsafe { set (CLEANUP . force () , RUN) } } else { debug_assert_eq ! (state , RUN) ; crate :: rt :: thread_cleanup () ; } } }